function initTabNavigation(){const e=document.querySelectorAll(".vak-tab"),t=document.querySelectorAll(".vak-section");e.forEach(n=>{n.addEventListener("click",()=>{const a=n.dataset.tab;e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),n.classList.add("active");const i=document.getElementById(a);i&&(i.classList.add("active"),i.scrollIntoView({behavior:"smooth",block:"start"}))})})}function initThemeToggle(){const e=document.getElementById("theme-toggle");if(!e)return;updateThemeIcon(localStorage.getItem("theme")||"dark"),e.addEventListener("click",()=>{const e=document.body;e.classList.contains("light-theme")?(e.classList.remove("light-theme"),localStorage.setItem("theme","dark"),updateThemeIcon("dark")):(e.classList.add("light-theme"),localStorage.setItem("theme","light"),updateThemeIcon("light"))})}function updateThemeIcon(e){const t=document.getElementById("theme-toggle");t&&(t.textContent="light"===e?"🌙":"☀️")}function initMobileMenu(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&(e.addEventListener("click",()=>{const n="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",!n),t.classList.toggle("active")}),document.addEventListener("click",n=>{e.contains(n.target)||t.contains(n.target)||(t.classList.remove("active"),e.setAttribute("aria-expanded","false"))}))}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),initThemeToggle(),initMobileMenu()});